"use strict";
const $=id=>document.getElementById(id), NS="http://www.w3.org/2000/svg";
let catalog,trace,filter=0,plant=1,playing=false,lastFrame=0,playhead=0,loadId=0;
const fmt=(n,d=1)=>Number(n).toFixed(d), deg=n=>`${fmt(n)}°`;
const statusNames={"ANGLE ALIGNED":"角度已对齐","TRACKING ANGLE":"正在跟随","CATCHING UP / TARGET PRESERVED":"正在补齐累计转角","ODOMETRY STALE (TURN OFF)":"里程计超时 · 转向暂停","BODY YAW JUMP (TURN OFF)":"身体读数跳变 · 转向暂停","INVALID BODY HEADING (TURN OFF)":"身体姿态无效 · 转向暂停","NO TURN PROGRESS / TARGET DROPPED":"无转动进展 · 目标已取消"};
function el(tag,attrs={},text){const n=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(text!=null)n.textContent=text;return n;}
function drawChart(id,columns,colors,width,height){
 const svg=$(id);svg.replaceChildren();const horizon=Number($("horizon").value), rows=trace.rows.filter(r=>r[0]<=horizon);const left=53,right=17,top=18,bottom=30;
 let low=Math.min(0,...rows.flatMap(r=>columns.map(c=>r[c]))),high=Math.max(0,...rows.flatMap(r=>columns.map(c=>r[c])));const pad=Math.max((high-low)*.09,id==="angleChart"?3:.02);low-=pad;high+=pad;
 const x=t=>left+t/horizon*(width-left-right), y=v=>top+(high-v)/(high-low)*(height-top-bottom);
 for(let i=0;i<=4;i++){let v=low+(high-low)*i/4;svg.append(el("line",{x1:left,y1:y(v),x2:width-right,y2:y(v),stroke:"#e6ecf3"}));svg.append(el("text",{x:left-9,y:y(v)+4,"text-anchor":"end"},fmt(v,id==="angleChart"?0:2)));}
 for(let i=0;i<=4;i++){const t=horizon*i/4;svg.append(el("text",{x:x(t),y:height-6,"text-anchor":"middle"},`${fmt(t,0)}s`));}
 columns.forEach((c,i)=>{const points=rows.map((r,j)=>`${j?"L":"M"}${x(r[0]).toFixed(1)},${y(r[c]).toFixed(1)}`).join(" ");svg.append(el("path",{d:points,fill:"none",stroke:colors[i],"stroke-width":c===3?2.5:1.7,...(c===4?{"stroke-dasharray":"5 4"}:{})}));});
 svg.append(el("line",{id:`${id}Cursor`,x1:0,x2:0,y1:top,y2:height-bottom,stroke:"#283f60","stroke-width":1,"stroke-dasharray":"3 4"}));
 svg.dataset.left=left;svg.dataset.plotWidth=width-left-right;
 svg.onclick=e=>{const rect=svg.getBoundingClientRect();const t=((e.clientX-rect.left)/rect.width*width-left)/(width-left-right)*horizon;$("time").value=Math.max(0,Math.min(horizon,t));renderCursor();};
}
function renderCursor(){if(!trace)return;const t=Number($("time").value),r=trace.rows[Math.min(trace.rows.length-1,Math.round(t*10))];$("timeValue").value=`${fmt(r[0])} s`;$("bodyAngle").textContent=deg(r[1]);$("robotAngle").textContent=deg(r[3]);$("instantError").textContent=deg(r[5]);$("linear").textContent=`${fmt(r[7],3)} m/s`;$("angular").textContent=`${fmt(r[6],3)} rad/s`;
 $("bodyNeedle").setAttribute("transform",`rotate(${-r[1]} 50 50)`);$("robotNeedle").setAttribute("transform",`rotate(${-r[3]} 50 50)`);
 const event=trace.events.filter(e=>e.t<=t).at(-1);$("status").textContent=statusNames[event?.status]||event?.status||"等待数据";
 for(const id of ["angleChart","commandChart"]){const svg=$(id),cursor=$(`${id}Cursor`),h=Number($("horizon").value);const x=Number(svg.dataset.left)+Math.min(t,h)/h*Number(svg.dataset.plotWidth);cursor.setAttribute("x1",x);cursor.setAttribute("x2",x);cursor.style.display=t>h?"none":"";}
}
function draw(){drawChart("angleChart",[1,2,4,3],["#929baa","#0b57d0","#067568","#c95811"],900,290);drawChart("commandChart",[6],["#0b57d0"],600,210);renderCursor();}
function setPlaying(v){playing=v;$("play").textContent=v?"Ⅱ 暂停":"▶ 播放";lastFrame=0;playhead=Number($("time").value);}
async function loadTrace(){const request=++loadId;setPlaying(false);$("results").setAttribute("aria-busy","true");$("play").disabled=$("download").disabled=true;$("error").hidden=true;try{const s=$("scenario").value;const res=await fetch(`traces/${s}-${filter}-${plant}.json`);if(!res.ok)throw Error(`无法读取仿真结果 (${res.status})`);const value=await res.json();if(request!==loadId)return;trace=value;$("note").textContent=catalog.scenarios.find(x=>x.id===s).note;const end=trace.rows.at(-1);$("finalGap").textContent=deg(end[1]-end[3]);$("finalError").textContent=deg(end[5]);$("peak").textContent=`${fmt(trace.peakAngular,3)} rad/s`;
 $("events").replaceChildren(...trace.events.map(e=>{const li=document.createElement("li");li.textContent=`${fmt(e.t)} s · ${statusNames[e.status]||e.status}`;return li;}));draw();$("play").disabled=$("download").disabled=false;$("results").setAttribute("aria-busy","false");}catch(e){if(request!==loadId)return;$("error").textContent=`${e.message}。请重新选择场景，或刷新页面。`;$("error").hidden=false;$("results").setAttribute("aria-busy","false");}}
function options(id,items,type){$(id).replaceChildren(...items.map((x,i)=>{const label=document.createElement("label");label.className="option";const input=document.createElement("input");input.type="radio";input.name=type;input.value=i;input.checked=i===(type==="filter"?filter:plant);input.onchange=()=>{if(type==="filter")filter=i;else plant=i;loadTrace();};label.append(input,document.createTextNode(x.name));const small=document.createElement("small");small.textContent=type==="filter"?`角度 ${fmt(x.angle,2)} s · 转速 ${fmt(x.rate,2)} s`:`增益 ${x.gain} · 延迟 ${x.delay} s · 惯性 ${x.lag} s`;label.append(small);return label;}));}
$("time").oninput=()=>{setPlaying(false);renderCursor();};$("horizon").onchange=()=>{if(trace)draw();};$("scenario").onchange=loadTrace;$("play").onclick=()=>{if(Number($("time").value)>=120)$("time").value=0;setPlaying(!playing);};
$("download").onclick=()=>{if(!trace)return;const header="time_s,body_deg,target_world_deg,robot_true_deg,odom_delayed_world_deg,error_deg,angular_rad_s,linear_m_s,x_m,y_m";const blob=new Blob([header+"\n"+trace.rows.map(r=>r.join(",")).join("\n")],{type:"text/csv;charset=utf-8"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`${trace.scenario}-filter${trace.filter}-plant${trace.plant}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function animate(now){if(playing&&trace){if(lastFrame){const t=Math.min(120,playhead+(now-lastFrame)/1000*Number($("speed").value));playhead=t;$("time").value=t;renderCursor();if(t>=120)setPlaying(false);}lastFrame=now;}requestAnimationFrame(animate);}requestAnimationFrame(animate);
async function init(){try{const res=await fetch("catalog.json");if(!res.ok)throw Error("仿真目录尚未生成");catalog=await res.json();$("scenario").replaceChildren(...catalog.scenarios.map(s=>{const o=document.createElement("option");o.value=s.id;o.textContent=s.name;return o;}));$("scenario").value="turn360";options("filters",catalog.filters,"filter");options("plants",catalog.plants,"plant");$("provenance").textContent=`生成时间：${new Date(catalog.generatedUtc).toLocaleString("zh-CN")}。控制器源码 SHA-256：${catalog.controllerSha256}。修改控制器后需重新生成仿真结果。`;await loadTrace();}catch(e){$("error").hidden=false;$("error").textContent=e.message;}}
// Optional WebMCP exposes the same bounded choices as the visible controls.
const modelContext=document.modelContext || navigator.modelContext;
const lifecycle=new AbortController();
if(modelContext?.registerTool)try{Promise.resolve(modelContext.registerTool({name:"set_simulation",description:"选择一个已经由实际 C# 控制器运行的仿真场景、滤波组合和底盘模型。",inputSchema:{type:"object",properties:{scenario:{type:"string"},filter:{type:"integer",minimum:0,maximum:2},plant:{type:"integer",minimum:0,maximum:2}},required:["scenario","filter","plant"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async args=>{if(!catalog||!catalog.scenarios.some(s=>s.id===args.scenario)||![0,1,2].includes(args.filter)||![0,1,2].includes(args.plant))return{content:[{type:"text",text:"参数不在可选范围内"}],isError:true};$("scenario").value=args.scenario;filter=args.filter;plant=args.plant;options("filters",catalog.filters,"filter");options("plants",catalog.plants,"plant");await loadTrace();return{content:[{type:"text",text:JSON.stringify({scenario:trace?.scenario,filter,plant,final:trace?.rows.at(-1)})}]};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
window.addEventListener("pagehide",()=>lifecycle.abort(),{once:true});
init();
